  /**
   * @ignore
   * @method
   * @name predictfun#signEvmTransaction
   * @description builds and signs an EIP-1559 transaction, returning the raw
   * signedFlag hex
   * @param {object} tx the transaction fields
   * @param {string} privateKey the wallet private key
   * @returns {string} the signedFlag raw transaction
   */
  ccxt::any signEvmTransaction(ccxt::any tx, ccxt::any privateKey) override {
    ccxt::any accessList = this->rlpEncodeList(ccxt::list{});
    ccxt::any fields = ccxt::list{
        this->rlpEncodeBytes(
            this->intToRlpHex(this->safeInteger(tx, std::string("chainId")))),
        this->rlpEncodeBytes(
            this->hexToRlpBytes(this->safeString(tx, std::string("nonce")))),
        this->rlpEncodeBytes(this->hexToRlpBytes(
            this->safeString(tx, std::string("maxPriorityFeePerGas")))),
        this->rlpEncodeBytes(this->hexToRlpBytes(
            this->safeString(tx, std::string("maxFeePerGas")))),
        this->rlpEncodeBytes(
            this->hexToRlpBytes(this->safeString(tx, std::string("gasLimit")))),
        this->rlpEncodeBytes(
            this->remove0xPrefix(this->safeString(tx, std::string("to")))),
        this->rlpEncodeBytes(this->hexToRlpBytes(
            this->safeString(tx, std::string("value"), std::string("0x0")))),
        this->rlpEncodeBytes(this->remove0xPrefix(
            this->safeString(tx, std::string("data"), std::string("0x")))),
        accessList};
    ccxt::any payload = add(std::string("02"), this->rlpEncodeList(fields));
    ccxt::any hashHex =
        this->hash(this->base16ToBinary(payload), keccak, std::string("hex"));
    ccxt::any signature = ecdsa(hashHex, this->remove0xPrefix(privateKey),
                                secp256k1, ccxt::any{});
    ccxt::any rHex = this->safeString(signature, std::string("r"));
    ccxt::any sHex = this->safeString(signature, std::string("s"));
    rHex = this->padHexToEven(rHex);
    sHex = this->padHexToEven(sHex);
    ccxt::any yParity = this->safeInteger(signature, std::string("v"));
    ccxt::any signedFields = ccxt::list{};
    for (ccxt::any i = 0; isLessThan(i, getArrayLength(fields));
         postFixIncrement(i)) {
      arrayPush(signedFields, ::getValue(fields, i));
    }
    arrayPush(signedFields, this->rlpEncodeBytes(this->intToRlpHex(yParity)));
    arrayPush(signedFields, this->rlpEncodeBytes(rHex));
    arrayPush(signedFields, this->rlpEncodeBytes(sHex));
    return add(std::string("0x02"), this->rlpEncodeList(signedFields));
  }

  /**
   * @method
   * @name predictfun#approve
   * @description grants the on-chain approvals a wallet needs before it can
   * trade. The buy side is the USDT allowance the exchange spends, without
   * which every order is refused with
   * create_order_insufficient_collateral_allowance; the sell side is the
   * ERC-1155 approval over the outcome shares themselves. WITHOUT params.amount
   * THE BUY SIDE GRANTS AN UNLIMITED (max uint256) ALLOWANCE, pass
   * params.amount to bound it. sends real transactions signedFlag with the
   * privateKey and waits for each receipt, so the wallet needs BNB for gas
   * @see https://dev.predict.fun/how-to-create-or-cancel-orders-679306m0
   * @param {string} [outcome] unified outcome handle, used to pick the
   * contracts its market settles through
   * @param {object} [params] extra parameters
   * @param {string} [params.side] 'buy' for the collateral allowance (the
   * default), 'sell' for the outcome share approval
   * @param {string} [params.spender] approve this contract instead of resolving
   * it from the outcome
   * @param {string} [params.token] the contract to grant on, defaults to USDT
   * when buying and to the market's conditional tokens when selling
   * @param {float} [params.amount] the allowance in USDT, unlimited when
   * omitted, buy side only
   * @param {bool} [params.approved] pass false to revoke instead of grant, sell
   * side only
   * @param {string} [params.owner] the token holder, defaults to walletAddress
   * or the address of the privateKey
   * @param {string} [params.rpcUrl] the rpc to broadcast through, defaults to
   * the public endpoint for the chain
   * @param {string} [params.gasLimit] gas limit as hex, defaults to 0x186a0
   * @returns {object} the transaction receipt when buying, and the list of
   * receipts when selling - a neg risk market needs two
   */
  virtual std::shared_future<ccxt::any>
  approve(ccxt::any outcome = ccxt::any{}, ccxt::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->privateKey, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(" approve() requires a privateKey to "
                                       "sign the on-chain transaction"))));
                 }
                 ccxt::any side = this->safeStringLower(
                     params, std::string("side"), std::string("buy"));
                 ccxt::any chainId = this->safeInteger(
                     this->options, std::string("chainId"), 56);
                 ccxt::any chainKey = this->numberToString(chainId);
                 ccxt::any rpcUrls = this->safeDict(
                     this->options, std::string("rpcUrls"), ccxt::dict{});
                 ccxt::any rpcUrl =
                     this->safeString(params, std::string("rpcUrl"),
                                      this->safeString(rpcUrls, chainKey));
                 ccxt::any owner = this->safeString(
                     params, std::string("owner"), this->walletAddress);
                 if (isTrue(isEqual(owner, ccxt::any{}))) {
                   owner = this->ethGetAddressFromPrivateKey(this->privateKey);
                 }
                 ccxt::any gasLimit = this->safeString(
                     params, std::string("gasLimit"), std::string("0x186a0"));
                 // which of the four exchanges settles a market is a property
                 // of the market, so an approval granted for one of them is
                 // worth nothing on the others
                 ccxt::any isNegRisk = false;
                 ccxt::any isYieldBearing = false;
                 if (isTrue(!isEqual(outcome, ccxt::any{}))) {
                   awaitValue(this->loadOutcome(outcome));
                   ccxt::any outcomeObj = this->outcome(outcome);
                   ccxt::any marketSymbol =
                       this->safeString(outcomeObj, std::string("market"));
                   ccxt::any marketObj = this->safeDict(
                       this->markets, marketSymbol, ccxt::dict{});
                   ccxt::any marketRow = this->safeDict(
                       marketObj, std::string("info"), ccxt::dict{});
                   isNegRisk = this->safeBool(marketRow,
                                              std::string("isNegRisk"), false);
                   isYieldBearing = this->safeBool(
                       marketRow, std::string("isYieldBearing"), false);
                 }
                 if (isTrue(isEqual(side, std::string("sell")))) {
                   ccxt::any ctfToken =
                       this->safeString(params, std::string("token"),
                                        this->conditionalTokensAddress(
                                            isNegRisk, isYieldBearing));
                   ccxt::any operators = ccxt::list{};
                   ccxt::any explicitOperator =
                       this->safeString(params, std::string("spender"));
                   if (isTrue(!isEqual(explicitOperator, ccxt::any{}))) {
                     arrayPush(operators, explicitOperator);
                   } else if (isTrue(isEqual(outcome, ccxt::any{}))) {
                     throw ArgumentsRequired(toString(add(
                         this->id,
                         std::string(
                             " approve() requires an \"outcome\" to resolve "
                             "the contracts to approve for selling, or an "
                             "explicit \"spender\" parameter"))));
                   } else {
                     arrayPush(operators, this->exchangeAddress(
                                              isNegRisk, isYieldBearing));
                     // a neg risk match mints and merges through the adapter,
                     // which moves the seller's shares itself, so approving the
                     // exchange alone leaves the sell side half open
                     if (isTrue(isNegRisk)) {
                       arrayPush(operators,
                                 this->adapterAddress(isYieldBearing));
                     }
                   }
                   if (isTrue(isTrue((isEqual(rpcUrl, ccxt::any{}))) ||
                              isTrue((isEqual(ctfToken, ccxt::any{}))))) {
                     throw ArgumentsRequired(toString(add(
                         add(this->id,
                             std::string(
                                 " approve() could not resolve the \"rpcUrl\" "
                                 "or the conditional tokens for chain ")),
                         chainKey)));
                   }
                   ccxt::any approved =
                       this->safeBool(params, std::string("approved"), true);
                   ccxt::any approvedHex =
                       std::string("0000000000000000000000000000000000000000000"
                                   "000000000000000000000");
                   if (isTrue(approved)) {
                     approvedHex =
                         std::string("00000000000000000000000000000000000000000"
                                     "00000000000000000000001");
                   }
                   ccxt::any receipts = ccxt::list{};
                   ccxt::any operatorsLength = getArrayLength(operators);
                   for (ccxt::any i = 0; isLessThan(i, operatorsLength);
                        postFixIncrement(i)) {
                     ccxt::any operatorAddress = ::getValue(operators, i);
                     if (isTrue(isEqual(operatorAddress, ccxt::any{}))) {
                       throw ArgumentsRequired(toString(add(
                           add(this->id,
                               std::string(" approve() could not resolve the "
                                           "operator to approve for chain ")),
                           chainKey)));
                     }
                     // setApprovalForAll(operator, approved) -> selector
                     // 0xa22cb465
                     ccxt::any approvalData =
                         add(add(std::string("0xa22cb465"),
                                 this->padHexAddress(operatorAddress)),
                             approvedHex);
                     // each receipt is awaited before the next transaction goes
                     // out, so the nonce the second one looks up already counts
                     // the first
                     ccxt::any approvalHash =
                         awaitValue(this->sendEvmTransaction(
                             rpcUrl, chainId, owner, ctfToken,
                             std::string("0x0"), approvalData, gasLimit));
                     ccxt::any receipt = awaitValue(
                         this->waitForTransactionReceipt(rpcUrl, approvalHash));
                     arrayPush(receipts, receipt);
                   }
                   return receipts;
                 }
                 ccxt::any collaterals = this->safeDict(
                     this->options, std::string("collateral"), ccxt::dict{});
                 ccxt::any token =
                     this->safeString(params, std::string("token"),
                                      this->safeString(collaterals, chainKey));
                 ccxt::any spender =
                     this->safeString(params, std::string("spender"));
                 if (isTrue(isEqual(spender, ccxt::any{}))) {
                   if (isTrue(isEqual(outcome, ccxt::any{}))) {
                     throw ArgumentsRequired(toString(add(
                         this->id,
                         std::string(" approve() requires an \"outcome\" to "
                                     "resolve the exchange to approve, or an "
                                     "explicit \"spender\" parameter"))));
                   }
                   spender = this->exchangeAddress(isNegRisk, isYieldBearing);
                 }
                 if (isTrue(isTrue(isTrue((isEqual(rpcUrl, ccxt::any{}))) ||
                                   isTrue((isEqual(token, ccxt::any{})))) ||
                            isTrue((isEqual(spender, ccxt::any{}))))) {
                   throw ArgumentsRequired(toString(add(
                       add(this->id,
                           std::string(
                               " approve() could not resolve the \"rpcUrl\", "
                               "the \"token\" or the \"spender\" for chain ")),
                       chainKey)));
                 }
                 ccxt::any amountHex =
                     std::string("fffffffffffffffffffffffffffffffffffffffffffff"
                                 "fffffffffffffffffff");
                 ccxt::any amount =
                     this->safeString(params, std::string("amount"));
                 if (isTrue(!isEqual(amount, ccxt::any{}))) {
                   // the collateral has eighteen decimals, so the scaled amount
                   // runs past what a float can hold - it has to stay a string
                   // all the way into the bigint
                   ccxt::any scaled = ccxt::Precise::stringMul(
                       amount, std::string("1000000000000000000"));
                   ccxt::any amountInt = this->decimalToPrecision(
                       scaled, TRUNCATE, 0, DECIMAL_PLACES);
                   ccxt::any amountBase16 =
                       this->intToBase16(this->convertToBigInt(amountInt));
                   amountHex = padStart(amountBase16, 64, std::string("0"));
                 }
                 // approve(spender, amount) -> selector 0x095ea7b3
                 ccxt::any approveData = add(add(std::string("0x095ea7b3"),
                                                 this->padHexAddress(spender)),
                                             amountHex);
                 ccxt::any txHash = awaitValue(this->sendEvmTransaction(
                     rpcUrl, chainId, owner, token, std::string("0x0"),
                     approveData, gasLimit));
                 return awaitValue(
                     this->waitForTransactionReceipt(rpcUrl, txHash));
               })
        .share();
  }

  /**
   * @method
   * @name predictfun#watchOrderBook
   * @description subscribes to the live order book of an outcome and returns it
   * as it updates
   * @see https://dev.predict.fun/subscription-topics-1915507m0
   * @param {string} outcome unified outcome handle
   * @param {int} [limit] the maximum number of price levels to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [prediction order book
   * structure](https://docs.ccxt.com/#/?id=prediction-order-book-structure)
   */
  std::shared_future<ccxt::any>
  watchOrderBook(ccxt::any outcome, ccxt::any limit = ccxt::any{},
                 ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->loadOutcome(outcome));
                 ccxt::any outcomeObj = this->outcome(outcome);
                 ccxt::any info = this->safeDict(
                     outcomeObj, std::string("info"), ccxt::dict{});
                 ccxt::any marketId =
                     this->safeString(info, std::string("marketId"));
                 if (isTrue(isEqual(marketId, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       add(this->id, std::string(" watchOrderBook() could not "
                                                 "resolve the market id of ")),
                       outcome)));
                 }
                 ccxt::any outcomeHandle =
                     this->safeOutcomeSymbol(ccxt::any{}, outcomeObj);
                 // the venue publishes one book per market, quoted on the yes
                 // side, and the no side is its complement - so a single
                 // subscription serves both outcomes and each waits on its own
                 // hash
                 ccxt::any topic =
                     add(std::string("predictOrderbook/"), marketId);
                 ccxt::any messageHash =
                     add(std::string("orderbook::"), outcomeHandle);
                 ccxt::any requestId = this->requestId();
                 ccxt::any request = ccxt::dict{
                     {std::string("method"), std::string("subscribe")},
                     {std::string("requestId"), requestId},
                     {std::string("params"), ccxt::list{topic}},
                 };
                 // the subscription travels as a dict rather than the default
                 // boolean: a reply carries only the request id, so every
                 // registered subscription is indexed on it - and indexBy
                 // cannot look inside a boolean. both outcomes wait on this one
                 // topic, so a rejected request has to be able to release both
                 // of them
                 ccxt::any subscription = ccxt::dict{
                     {std::string("id"), this->numberToString(requestId)},
                     {std::string("topic"), topic},
                     {std::string("subscribeHash"), topic},
                     {std::string("messageHashes"),
                      this->orderBookMessageHashes(marketId)},
                 };
                 ccxt::any url = this->socketUrl();
                 ccxt::any orderbook = awaitValue(this->watch(
                     url, messageHash, this->extend(request, params), topic,
                     subscription));
                 return ::wsLimit(orderbook);
               })
        .share();
  }

  /**
   * @method
   * @name predictfun#unWatchOrderBook
   * @description stops watching the order book of an outcome. the venue
   * publishes one book per market and both of its outcomes read it, so the
   * sibling outcome is released with it
   * @see https://dev.predict.fun/subscription-topics-1915507m0
   * @param {string} outcome unified outcome handle
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {any} the venue's acknowledgement
   */
  std::shared_future<ccxt::any>
  unWatchOrderBook(ccxt::any outcome,
                   ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->loadOutcome(outcome));
                 ccxt::any outcomeObj = this->outcome(outcome);
                 ccxt::any info = this->safeDict(
                     outcomeObj, std::string("info"), ccxt::dict{});
                 ccxt::any marketId =
                     this->safeString(info, std::string("marketId"));
                 if (isTrue(isEqual(marketId, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(add(this->id,
                               std::string(" unWatchOrderBook() could not "
                                           "resolve the market id of ")),
                           outcome)));
                 }
                 ccxt::any topic =
                     add(std::string("predictOrderbook/"), marketId);
                 ccxt::any outcomes = this->outcomesByMarketId(marketId);
                 ccxt::any outcomesLength = getArrayLength(outcomes);
                 ccxt::any handles = ccxt::list{};
                 ccxt::any subMessageHashes = ccxt::list{};
                 ccxt::any messageHashes = ccxt::list{};
                 for (ccxt::any i = 0; isLessThan(i, outcomesLength);
                      postFixIncrement(i)) {
                   ccxt::any handle = this->safeString(::getValue(outcomes, i),
                                                       std::string("outcome"));
                   if (isTrue(!isEqual(handle, ccxt::any{}))) {
                     arrayPush(handles, handle);
                     arrayPush(subMessageHashes,
                               add(std::string("orderbook::"), handle));
                     arrayPush(
                         messageHashes,
                         add(std::string("unsubscribe::orderbook::"), handle));
                   }
                 }
                 ccxt::any requestId = this->requestId();
                 ccxt::any request = ccxt::dict{
                     {std::string("method"), std::string("unsubscribe")},
                     {std::string("requestId"), requestId},
                     {std::string("params"), ccxt::list{topic}},
                 };
                 // the acknowledgement carries the request id and nothing else
                 // - no topic - so the id is what ties the reply back to this
                 // subscription, which travels with it as the last argument
                 ccxt::any subscription = ccxt::dict{
                     {std::string("unsubscribe"), true},
                     {std::string("id"), this->numberToString(requestId)},
                     {std::string("topic"), std::string("orderbook")},
                     {std::string("symbols"), handles},
                     {std::string("subMessageHashes"), subMessageHashes},
                     {std::string("messageHashes"), messageHashes},
                     {std::string("subscribeHash"), topic},
                 };
                 ccxt::any messageHash =
                     add(std::string("unsubscribe::orderbook::"),
                         this->safeOutcomeSymbol(ccxt::any{}, outcomeObj));
                 ccxt::any url = this->socketUrl();
                 return awaitValue(this->watch(url, messageHash,
                                               this->extend(request, params),
                                               messageHash, subscription));
               })
        .share();
  }

  /**
   * @ignore
   * @method
   * @name predictfun#orderBookMessageHashes
   * @description the hashes every waiter on a market's book is parked on, one
   * per outcome
   * @param {string} [marketId] the venue market id
   * @returns {string[]} the message hashes
   */
  virtual ccxt::any orderBookMessageHashes(ccxt::any marketId) {
    ccxt::any outcomes = this->outcomesByMarketId(marketId);
    ccxt::any outcomesLength = getArrayLength(outcomes);
    ccxt::any hashes = ccxt::list{};
    for (ccxt::any i = 0; isLessThan(i, outcomesLength); postFixIncrement(i)) {
      ccxt::any handle =
          this->safeString(::getValue(outcomes, i), std::string("outcome"));
      if (isTrue(!isEqual(handle, ccxt::any{}))) {
        arrayPush(hashes, add(std::string("orderbook::"), handle));
      }
    }
    return hashes;
  }

  /**
   * @ignore
   * @method
   * @name predictfun#handleSubscriptionError
   * @description releases the one request the venue turned down and leaves the
   * rest of the connection alone
   * @param {Client} client the websocket client
   * @param {object} message the raw rejection
   * @param {object} subscription the subscription that request registered,
   * empty when it cannot be attributed
   */
  virtual void handleSubscriptionError(ccxt::any client, ccxt::any message,
                                       ccxt::any subscription) {
    ccxt::any rawError =
        this->safeDict(message, std::string("error"), ccxt::dict{});
    ExchangeError error = ExchangeError(
        add(add(this->id, std::string(" subscribe request rejected ")),
            this->json(rawError)));
    // watch () registers a subscription before it sends and only sends while
    // the hash is still unregistered, so a rejected request has to take its own
    // entry down - otherwise a retry would skip the send and wait forever on a
    // topic the venue never accepted
    ccxt::any subscribeHash =
        this->safeString(subscription, std::string("subscribeHash"));
    if (isTrue(isTrue((!isEqual(subscribeHash, ccxt::any{}))) &&
               isTrue((inOp(::getValue(client, std::string("subscriptions")),
                            subscribeHash))))) {
      deleteKey(::getValue(client, std::string("subscriptions")),
                subscribeHash);
    }
    ccxt::any messageHashes = this->safeList(
        subscription, std::string("messageHashes"), ccxt::list{});
    if (isTrue(isEqual(this->safeString(subscription, std::string("topic")),
                       std::string("walletEvents")))) {
      // watch () registers the wallet subscription once, for whichever watcher
      // came first, so its list is a snapshot of that moment - a narrowed
      // watcher that joined later is known only to the client. read the live
      // waiters now, or those later callers would never be rejected and, with
      // the subscription gone below, never retried or torn down either
      messageHashes = this->walletEventMessageHashes(client);
    }
    ccxt::any messageHashesLength = getArrayLength(messageHashes);
    if (isTrue(isEqual(messageHashesLength, 0))) {
      throw;
    }
    for (ccxt::any i = 0; isLessThan(i, messageHashesLength);
         postFixIncrement(i)) {
      this->reject(error, ::getValue(messageHashes, i));
    }
  }

  /**
   * @ignore
   * @method
   * @name predictfun#handleUnSubscription
   * @description tears down what an acknowledged unsubscribe leaves behind
   * @param {Client} client the websocket client
   * @param {object} subscription the subscription the acknowledged request id
   * belongs to
   */
  virtual void handleUnSubscription(ccxt::any client, ccxt::any subscription) {
    ccxt::any messageHashes = this->safeList(
        subscription, std::string("messageHashes"), ccxt::list{});
    ccxt::any subMessageHashes = this->safeList(
        subscription, std::string("subMessageHashes"), ccxt::list{});
    ccxt::any messageHashesLength = getArrayLength(messageHashes);
    // one wallet hash stands for a family: 'orders' is what an unnarrowed
    // caller waits on and 'orders::<outcome>' what a narrowed one waits on, so
    // the base matches it as a prefix and releases both. the book path needs no
    // such thing - it registers the full narrowed hash of every outcome of the
    // market, and an exact match is what keeps a sibling market out of it
    ccxt::any isWalletTopic =
        (isEqual(this->safeString(subscription, std::string("topic")),
                 std::string("walletEvents")));
    for (ccxt::any i = 0; isLessThan(i, messageHashesLength);
         postFixIncrement(i)) {
      this->cleanUnsubscription(client, ::getValue(subMessageHashes, i),
                                ::getValue(messageHashes, i), isWalletTopic);
    }
    this->cleanCache(subscription);
    // the subscription itself is keyed by the topic, which is what
    // watchOrderBook registered - leaving it behind would make a later watch
    // believe it is still subscribed
    ccxt::any subscribeHash =
        this->safeString(subscription, std::string("subscribeHash"));
    if (isTrue(isTrue((!isEqual(subscribeHash, ccxt::any{}))) &&
               isTrue((inOp(::getValue(client, std::string("subscriptions")),
                            subscribeHash))))) {
      deleteKey(::getValue(client, std::string("subscriptions")),
                subscribeHash);
    }
    // cleanCache drops a cache only when the subscription names that one topic,
    // and the wallet topic backs two of them - so the caches it cannot reach
    // are dropped here by the hashes the subscription does list. a stale cache
    // left behind would be served to the next watcher as if it had just arrived
    // the reset is delegated to the base rather than written here: assigning
    // undefined to an inherited cache from a derived class is dropped outright
    // by the go and c# transpilers, silently leaving those two languages with a
    // stale cache
    ccxt::any subMessageHashesLength = getArrayLength(subMessageHashes);
    for (ccxt::any i = 0; isLessThan(i, subMessageHashesLength);
         postFixIncrement(i)) {
      ccxt::any subHash = ::getValue(subMessageHashes, i);
      if (isTrue(isTrue((isEqual(subHash, std::string("orders")))) ||
                 isTrue((isEqual(subHash, std::string("myTrades")))))) {
        this->cleanCache(ccxt::dict{
            {std::string("topic"), subHash},
        });
      }
    }
  }

  /**
   * @method
   * @name predictfun#watchOrders
   * @description watches the wallet's own orders as the venue accepts, fills,
   * expires or cancels them
   * @see https://dev.predict.fun/subscription-topics-1915507m0
   * @param {string} [outcome] unified outcome handle to narrow the stream to
   * @param {int} [since] timestamp in ms of the earliest order to return
   * @param {int} [limit] the maximum number of orders to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} a list of [prediction order
   * structures](https://docs.ccxt.com/#/?id=prediction-order-structure)
   */
  std::shared_future<ccxt::any>
  watchOrders(ccxt::any outcome = ccxt::any{}, ccxt::any since = ccxt::any{},
              ccxt::any limit = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 ccxt::any messageHash = std::string("orders");
                 if (isTrue(!isEqual(outcome, ccxt::any{}))) {
                   awaitValue(this->loadOutcome(outcome));
                   ccxt::any outcomeObj = this->outcome(outcome);
                   outcome = this->safeOutcomeSymbol(ccxt::any{}, outcomeObj);
                   messageHash = add(std::string("orders::"), outcome);
                 } else {
                   // events arrive for whatever market the wallet traded, and
                   // the handler that resolves them is synchronous - so the
                   // universe is warmed here, while there is still a place to
                   // await. without it the first events land on a cold cache
                   // and every one of them buckets into the cache under the
                   // same undefined outcome. the call is idempotent and returns
                   // without a request once the cache is warm
                   awaitValue(this->loadOutcomes());
                 }
                 ccxt::any orders =
                     awaitValue(this->watchWalletEvents(messageHash, params));
                 if (isTrue(this->newUpdates)) {
                   limit = ::wsGetLimit(orders, outcome, limit);
                 }
                 return this->filterByOutcomeSinceLimit(orders, outcome, since,
                                                        limit, true);
               })
        .share();
  }

  /**
   * @method
   * @name predictfun#watchMyTrades
   * @description watches the wallet's own fills as they settle on chain
   * @see https://dev.predict.fun/subscription-topics-1915507m0
   * @param {string} [outcome] unified outcome handle to narrow the stream to
   * @param {int} [since] timestamp in ms of the earliest trade to return
   * @param {int} [limit] the maximum number of trades to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} a list of [prediction trade
   * structures](https://docs.ccxt.com/#/?id=prediction-trade-structure)
   */
  std::shared_future<ccxt::any>
  watchMyTrades(ccxt::any outcome = ccxt::any{}, ccxt::any since = ccxt::any{},
                ccxt::any limit = ccxt::any{},
                ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 ccxt::any messageHash = std::string("myTrades");
                 if (isTrue(!isEqual(outcome, ccxt::any{}))) {
                   awaitValue(this->loadOutcome(outcome));
                   ccxt::any outcomeObj = this->outcome(outcome);
                   outcome = this->safeOutcomeSymbol(ccxt::any{}, outcomeObj);
                   messageHash = add(std::string("myTrades::"), outcome);
                 } else {
                   // same as watchOrders (): the fills come from the one wallet
                   // topic and are resolved by a synchronous handler, so the
                   // cache is warmed here rather than on the first event
                   awaitValue(this->loadOutcomes());
                 }
                 ccxt::any trades =
                     awaitValue(this->watchWalletEvents(messageHash, params));
                 if (isTrue(this->newUpdates)) {
                   limit = ::wsGetLimit(trades, outcome, limit);
                 }
                 return this->filterByOutcomeSinceLimit(trades, outcome, since,
                                                        limit, true);
               })
        .share();
  }

  /**
   * @method
   * @name predictfun#unWatchOrders
   * @description stops watching the wallet's orders. one wallet topic carries
   * orders and fills alike, so both streams are released together
   * @see https://dev.predict.fun/subscription-topics-1915507m0
   * @param {string} [outcome] not used by predictfun.unWatchOrders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {any} the venue's acknowledgement
   */
  std::shared_future<ccxt::any>
  unWatchOrders(ccxt::any outcome = ccxt::any{},
                ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        return awaitValue(this->unWatchWalletEvents(
                            std::string("orders"), params));
                      })
        .share();
  }

  /**
   * @method
   * @name predictfun#unWatchMyTrades
   * @description stops watching the wallet's fills. one wallet topic carries
   * orders and fills alike, so both streams are released together
   * @see https://dev.predict.fun/subscription-topics-1915507m0
   * @param {string} [outcome] not used by predictfun.unWatchMyTrades
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {any} the venue's acknowledgement
   */
  std::shared_future<ccxt::any>
  unWatchMyTrades(ccxt::any outcome = ccxt::any{},
                  ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        return awaitValue(this->unWatchWalletEvents(
                            std::string("myTrades"), params));
                      })
        .share();
  }

  /**
   * @ignore
   * @method
   * @name predictfun#walletEventsTopic
   * @description the wallet topic, which carries the jwt inside the topic
   * string itself
   * @returns {string} the topic to subscribe to
   */
  virtual std::shared_future<ccxt::any> walletEventsTopic() {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 // authenticate () serves the cached token until it expires, so
                 // subscribe and unsubscribe name the same topic. a re-minted
                 // token is a different topic, which is why the socket
                 // subscription is keyed by a stable hash instead of by this
                 // string - the token is a secret and has no business sitting
                 // in a subscription key the local is not called jwt: that is
                 // the name of a base method, and the regex transpiler rewrites
                 // such identifiers into self.jwt, which lands as a broken
                 // assignment in python
                 ccxt::any walletToken = awaitValue(this->authenticate());
                 return add(std::string("predictWalletEvents/"), walletToken);
               })
        .share();
  }

  /**
   * @ignore
   * @method
   * @name predictfun#watchWalletEvents
   * @description subscribes to the wallet topic and waits on the hash the
   * caller's method reads
   * @param {string} messageHash the hash the caller waits on
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {any} whatever the channel resolves with
   */
  virtual std::shared_future<ccxt::any>
  watchWalletEvents(ccxt::any messageHash, ccxt::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 ccxt::any topic = awaitValue(this->walletEventsTopic());
                 ccxt::any requestId = this->requestId();
                 ccxt::any request = ccxt::dict{
                     {std::string("method"), std::string("subscribe")},
                     {std::string("requestId"), requestId},
                     {std::string("params"), ccxt::list{topic}},
                 };
                 ccxt::any url = this->socketUrl();
                 ccxt::any client = this->client(url);
                 ccxt::any subscription = ccxt::dict{
                     {std::string("id"), this->numberToString(requestId)},
                     {std::string("topic"), std::string("walletEvents")},
                     {std::string("subscribeHash"),
                      std::string("walletEvents")},
                     {std::string("messageHashes"),
                      this->walletEventMessageHashes(client, messageHash)},
                 };
                 return awaitValue(this->watch(
                     url, messageHash, this->extend(request, params),
                     std::string("walletEvents"), subscription));
               })
        .share();
  }

  /**
   * @ignore
   * @method
   * @name predictfun#walletEventMessageHashes
   * @description the hashes every waiter on the wallet topic is parked on, the
   * narrowed ones included
   * @param {Client} client the websocket client
   * @param {string} [messageHash] the hash this call is about to park on, not
   * registered yet
   * @returns {string[]} the message hashes
   */
  virtual ccxt::any
  walletEventMessageHashes(ccxt::any client,
                           ccxt::any messageHash = ccxt::any{}) {
    // handleSubscriptionError rejects exactly this list, so a hash missing from
    // it belongs to a caller the venue's refusal never reaches - watchOrders
    // (outcome) would sit forever on a topic that was turned down. the
    // unnarrowed pair is always listed, the narrowed ones are whatever is
    // already live on this connection plus the hash watch () is about to
    // register
    ccxt::any hashes =
        ccxt::list{std::string("orders"), std::string("myTrades")};
    ccxt::any futures =
        getObjectKeys(::getValue(client, std::string("futures")));
    ccxt::any futuresLength = getArrayLength(futures);
    for (ccxt::any i = 0; isLessThan(i, futuresLength); postFixIncrement(i)) {
      ccxt::any future = ::getValue(futures, i);
      if (isTrue(isTrue((isEqual(getIndexOf(future, std::string("orders::")),
                                 0))) ||
                 isTrue((isEqual(getIndexOf(future, std::string("myTrades::")),
                                 0))))) {
        arrayPush(hashes, future);
      }
    }
    if (isTrue(isTrue((!isEqual(messageHash, ccxt::any{}))) &&
               !isTrue(this->inArray(messageHash, hashes)))) {
      arrayPush(hashes, messageHash);
    }
    return hashes;
  }

  /**
   * @ignore
   * @method
   * @name predictfun#unWatchWalletEvents
   * @description drops the wallet topic, releasing both the order and the fill
   * stream
   * @param {string} channel 'orders' or 'myTrades'
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {any} the venue's acknowledgement
   */
  virtual std::shared_future<ccxt::any>
  unWatchWalletEvents(ccxt::any channel, ccxt::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 ccxt::any topic = awaitValue(this->walletEventsTopic());
                 ccxt::any requestId = this->requestId();
                 ccxt::any request = ccxt::dict{
                     {std::string("method"), std::string("unsubscribe")},
                     {std::string("requestId"), requestId},
                     {std::string("params"), ccxt::list{topic}},
                 };
                 ccxt::any subscription = ccxt::dict{
                     {std::string("unsubscribe"), true},
                     {std::string("id"), this->numberToString(requestId)},
                     {std::string("topic"), std::string("walletEvents")},
                     {std::string("symbols"), ccxt::list{}},
                     {std::string("subMessageHashes"),
                      ccxt::list{std::string("orders"),
                                 std::string("myTrades")}},
                     {std::string("messageHashes"),
                      ccxt::list{std::string("unsubscribe::orders"),
                                 std::string("unsubscribe::myTrades")}},
                     {std::string("subscribeHash"),
                      std::string("walletEvents")},
                 };
                 ccxt::any messageHash =
                     add(std::string("unsubscribe::"), channel);
                 ccxt::any url = this->socketUrl();
                 return awaitValue(this->watch(url, messageHash,
                                               this->extend(request, params),
                                               messageHash, subscription));
               })
        .share();
  }

  /**
   * @ignore
   * @method
   * @name predictfun#socketUrl
   * @description the socket endpoint carrying the api key the venue demands on
   * the handshake
   * @returns {string} the url to connect to
   */
  virtual ccxt::any socketUrl() {
    ccxt::any urls = ::getValue(this->urls, std::string("api"));
    ccxt::any base = this->safeString(urls, std::string("ws"));
    if (isTrue(isEqual(base, ccxt::any{}))) {
      throw NotSupported(toString(
          add(this->id,
              std::string(" does not have a sandbox websocket endpoint"))));
    }
    if (isTrue(isEqual(this->apiKey, ccxt::any{}))) {
      throw AuthenticationError(toString(add(
          this->id,
          std::string(" requires an apiKey for all methods - the venue answers "
                      "the socket handshake with a 401 without one"))));
    }
    // the key rides in the query string rather than a header: a browser cannot
    // set headers on a websocket handshake, and the venue documents both forms
    return add(add(base, std::string("?apiKey=")), this->apiKey);
  }

  /**
   * @ignore
   * @method
   * @name predictfun#requestId
   * @description a monotonic id the venue echoes back so a subscription reply
   * can be matched to its request
   * @returns {int} the next request id
   */
  virtual ccxt::any requestId() {
    this->lockId();
    ccxt::any previous =
        this->safeInteger(this->options, std::string("requestId"), 0);
    ccxt::any next = this->sum(previous, 1);
    ::setValue(this->options, std::string("requestId"), next);
    this->unlockId();
    return next;
  }

  /**
   * @ignore
   * @method
   * @name predictfun#outcomeForToken
   * @description resolves the outcome a row belongs to from its own token id,
   * taking the caller's outcome only when it names that same token
   * @param {string} [tokenId] the on chain token id the row carries
   * @param {object} [market] the outcome the caller asked about
   * @returns {object} the outcome object, or a stub keyed by the token id when
   * it is not cached
   */
  virtual ccxt::any outcomeForToken(ccxt::any tokenId,
                                    ccxt::any market = ccxt::any{}) {
    // the list endpoints (orders, matches, positions) answer for the whole
    // wallet rather than for the outcome asked about, so the caller's outcome
    // is only a hint. safeOutcome falls back to it on any cache miss, which
    // stamped the requested outcome onto rows from other markets - and the
    // outcome filter afterwards then kept them, as they now matched
    ccxt::any hintId = this->safeString(market, std::string("outcomeId"));
    if (isTrue(isTrue((isEqual(tokenId, ccxt::any{}))) ||
               isTrue((isEqual(hintId, tokenId))))) {
      return this->safeOutcome(tokenId, market);
    }
    return this->safeOutcome(tokenId);
  }

  /**
   * @ignore
   * @method
   * @name predictfun#outcomesByMarketId
   * @description the cached outcomes that belong to one venue market id
   * @param {string} [marketId] the venue market id
   * @returns {object[]} the outcome objects
   */
  virtual ccxt::any outcomesByMarketId(ccxt::any marketId) {
    ccxt::any result = ccxt::list{};
    ccxt::any cached = this->outcomes;
    if (isTrue(isTrue((isEqual(marketId, ccxt::any{}))) ||
               isTrue((isEqual(cached, ccxt::any{}))))) {
      return result;
    }
    ccxt::any handles = getObjectKeys(cached);
    ccxt::any handlesLength = getArrayLength(handles);
    for (ccxt::any i = 0; isLessThan(i, handlesLength); postFixIncrement(i)) {
      ccxt::any outcomeObj = ::getValue(cached, ::getValue(handles, i));
      ccxt::any info =
          this->safeDict(outcomeObj, std::string("info"), ccxt::dict{});
      if (isTrue(isEqual(this->safeString(info, std::string("marketId")),
                         marketId))) {
        arrayPush(result, outcomeObj);
      }
    }
    return result;
  }

  /**
   * @ignore
   * @method
   * @name predictfun#handleOrderBook
   * @description turns a book message into the two complementary outcome books
   * of its market
   * @param {Client} client the websocket client
   * @param {object} message the raw message
   */
  virtual void handleOrderBook(ccxt::any client, ccxt::any message) {
    //
    //     {
    //         "type": "M",
    //         "topic": "predictOrderbook/2107",
    //         "data": {
    //             "asks": [
    //                 [ 0.029, 1478.08 ],
    //                 [ 0.03, 870.93 ]
    //             ],
    //             "bids": [
    //                 [ 0.02, 1386.724081632653 ],
    //                 [ 0.017, 2640.3371187742646 ]
    //             ],
    //             "lastOrderSettled": {
    //                 "id": "3172327577",
    //                 "kind": "LIMIT",
    //                 "marketId": 2107,
    //                 "outcome": "Yes",
    //                 "price": "0.02",
    //                 "side": "Bid"
    //             },
    //             "marketId": 2107,
    //             "orderCount": 62,
    //             "settlementsPending": {
    //                 "asks": [
    //                     [ 0.029, 0.14906 ]
    //                 ],
    //                 "bids": []
    //             },
    //             "updateTimestampMs": 1788953990223,
    //             "version": 1
    //         }
    //     }
    //
    ccxt::any data = this->safeDict(message, std::string("data"), ccxt::dict{});
    ccxt::any marketId = this->safeString(data, std::string("marketId"));
    ccxt::any timestamp =
        this->safeInteger(data, std::string("updateTimestampMs"));
    ccxt::any rawAsks = this->safeList(data, std::string("asks"), ccxt::list{});
    ccxt::any rawBids = this->safeList(data, std::string("bids"), ccxt::list{});
    // every message carries the whole book - the venue publishes no deltas -
    // and the levels arrive already sorted, best first
    ccxt::any yesBids = ccxt::list{};
    ccxt::any yesAsks = ccxt::list{};
    ccxt::any noBids = ccxt::list{};
    ccxt::any noAsks = ccxt::list{};
    ccxt::any bidsLength = getArrayLength(rawBids);
    for (ccxt::any i = 0; isLessThan(i, bidsLength); postFixIncrement(i)) {
      ccxt::any bid = ::getValue(rawBids, i);
      ccxt::any bidPrice = this->safeString(bid, 0);
      ccxt::any bidSize = this->parseNumber(this->safeString(bid, 1));
      arrayPush(yesBids, ccxt::list{this->parseNumber(bidPrice), bidSize});
      // a bid for yes at p is an offer of no at 1 - p
      arrayPush(noAsks, ccxt::list{this->parseNumber(ccxt::Precise::stringSub(
                                       std::string("1"), bidPrice)),
                                   bidSize});
    }
    ccxt::any asksLength = getArrayLength(rawAsks);
    for (ccxt::any i = 0; isLessThan(i, asksLength); postFixIncrement(i)) {
      ccxt::any ask = ::getValue(rawAsks, i);
      ccxt::any askPrice = this->safeString(ask, 0);
      ccxt::any askSize = this->parseNumber(this->safeString(ask, 1));
      arrayPush(yesAsks, ccxt::list{this->parseNumber(askPrice), askSize});
      arrayPush(noBids, ccxt::list{this->parseNumber(ccxt::Precise::stringSub(
                                       std::string("1"), askPrice)),
                                   askSize});
    }
    ccxt::any outcomes = this->outcomesByMarketId(marketId);
    ccxt::any outcomesLength = getArrayLength(outcomes);
    for (ccxt::any i = 0; isLessThan(i, outcomesLength); postFixIncrement(i)) {
      ccxt::any outcomeObj = ::getValue(outcomes, i);
      ccxt::any outcomeInfo =
          this->safeDict(outcomeObj, std::string("info"), ccxt::dict{});
      ccxt::any isYesOutcome =
          isEqual(this->safeInteger(outcomeInfo, std::string("indexSet")), 1);
      ccxt::any outcomeHandle =
          this->safeString(outcomeObj, std::string("outcome"));
      if (isTrue(!isEqual(outcomeHandle, ccxt::any{}))) {
        if (!isTrue((inOp(this->orderbooks, outcomeHandle)))) {
          ::setValue(this->orderbooks, outcomeHandle,
                     this->orderBook(ccxt::dict{}));
        }
        ccxt::any orderbook = ::getValue(this->orderbooks, outcomeHandle);
        ccxt::any bids = yesBids;
        ccxt::any asks = yesAsks;
        if (!isTrue(isYesOutcome)) {
          bids = this->sortBy(noBids, 0, true);
          asks = this->sortBy(noAsks, 0);
        }
        ::resetOrderBook(
            orderbook,
            ccxt::dict{
                {std::string("bids"), bids},
                {std::string("asks"), asks},
                {std::string("timestamp"), timestamp},
                {std::string("datetime"), this->iso8601(timestamp)},
                {std::string("outcome"), outcomeHandle},
                {std::string("outcomeId"),
                 this->safeString(outcomeObj, std::string("outcomeId"))},
                {std::string("market"),
                 this->safeString(outcomeObj, std::string("market"))},
                {std::string("nonce"),
                 this->safeInteger(data, std::string("version"))},
            });
        this->resolve(orderbook,
                      add(std::string("orderbook::"), outcomeHandle));
      }
    }
  }

  /**
   * @ignore
   * @method
   * @name predictfun#handleWalletEvent
   * @description turns one wallet event into the order it describes, and into a
   * trade when it settled
   * @param {Client} client the websocket client
   * @param {object} message the raw message
   */
  virtual void handleWalletEvent(ccxt::any client, ccxt::any message) {
    //
    //     {
    //         "type": "M",
    //         "topic":
    //         "predictWalletEvents/eyJ0eXAiOiJKV1QiLCJhbGciOiJIUzI1NiJ9...",
    //         "data": {
    //             "type": "orderTransactionSuccess",
    //             "orderId": "3420472350",
    //             "orderHash":
    //             "0x7d097327cc15754411b7ec3e3e074ff3e974394a75aa5c81fdf90b4e67e59c15",
    //             "settlementId": "01a08f55-d6f7-77e3-895e-81cf62d8aa09",
    //             "timestamp": 1789111162000,
    //             "walletAddress":
    //             "0xabababababababababababababababababababab", "isMaker":
    //             false, "fee": { "amountWei": "400000000000000", "type":
    //             "COLLATERAL" }, "fill": {
    //                 "executedPriceWei": "20000000000000000",
    //                 "executedSizeWei": "1000000000000000000",
    //                 "executedValueWei": "20000000000000000"
    //             },
    //             "details": {
    //                 "categorySlug":
    //                 "will-trump-acquire-greenland-before-2027", "marketId":
    //                 2107, "marketQuestion": "Will Trump acquire Greenland
    //                 before 2027?", "outcome": "YES", "outcomeIndex": 1,
    //                 "outcomeName": "Yes",
    //                 "price": "0.010",
    //                 "quantity": "1.000",
    //                 "quantityFilled": "1.000",
    //                 "quoteType": "ASK",
    //                 "strategyType": "MARKET",
    //                 "value": "0.01",
    //                 "valueFilled": "0.01"
    //             }
    //         }
    //     }
    //
    // the details block is the same on every variant and is quoted in units,
    // while fill and fee are quoted in wei. observed live: orderAccepted,
    // orderMarketMatchPlan (which the venue sends but does not document),
    // orderTransactionSubmitted, orderTransactionSuccess and orderCancelled -
    // the latter arrives with the same envelope and no fill
    //
    ccxt::any data = this->safeDict(message, std::string("data"), ccxt::dict{});
    ccxt::any order = this->parseWalletEventOrder(data);
    this->handleWalletEventOrder(client, order);
    // only a confirmed on-chain settlement is a trade: a submitted transaction
    // has not landed yet and a failed one never did, so neither belongs in
    // myTrades
    ccxt::any eventType = this->safeString(data, std::string("type"));
    if (isTrue(isEqual(eventType, std::string("orderTransactionSuccess")))) {
      this->handleWalletEventTrade(client, data, order);
    }
  }

  /**
   * @ignore
   * @method
   * @name predictfun#handleWalletEventOrder
   * @description stores the order a wallet event describes and wakes whoever
   * waits on it
   * @param {Client} client the websocket client
   * @param {object} order the parsed order
   */
  virtual void handleWalletEventOrder(ccxt::any client, ccxt::any order) {
    if (isTrue(isEqual(this->orders, ccxt::any{}))) {
      ccxt::any limit =
          this->safeInteger(this->options, std::string("ordersLimit"), 1000);
      this->orders = ccxt::ws::ArrayCacheByOutcomeById(limit);
    }
    ccxt::any stored = this->orders;
    ::wsAppend(stored, order);
    this->resolve(stored, std::string("orders"));
    ccxt::any outcomeHandle = this->safeString(order, std::string("outcome"));
    if (isTrue(!isEqual(outcomeHandle, ccxt::any{}))) {
      this->resolve(stored, add(std::string("orders::"), outcomeHandle));
    }
  }

  /**
   * @ignore
   * @method
   * @name predictfun#handleWalletEventTrade
   * @description stores the settled fill a wallet event carries and wakes
   * whoever waits on it
   * @param {Client} client the websocket client
   * @param {object} event the raw event
   * @param {object} order the order the same event was parsed into
   */
  virtual void handleWalletEventTrade(ccxt::any client, ccxt::any event,
                                      ccxt::any order) {
    ccxt::any trade = this->parseWalletEventTrade(event, order);
    if (isTrue(isEqual(this->myTrades, ccxt::any{}))) {
      ccxt::any limit =
          this->safeInteger(this->options, std::string("tradesLimit"), 1000);
      this->myTrades = ccxt::ws::ArrayCacheByOutcomeById(limit);
    }
    ccxt::any stored = this->myTrades;
    ::wsAppend(stored, trade);
    this->resolve(stored, std::string("myTrades"));
    ccxt::any outcomeHandle = this->safeString(trade, std::string("outcome"));
    if (isTrue(!isEqual(outcomeHandle, ccxt::any{}))) {
      this->resolve(stored, add(std::string("myTrades::"), outcomeHandle));
    }
  }

  /**
   * @ignore
   * @method
   * @name predictfun#walletEventOutcome
   * @description resolves the cached outcome a wallet event refers to, by
   * market and outcome index
   * @param {object} details the event's details block
   * @returns {object} the outcome object, or a stub when the market is not
   * cached
   */
  virtual ccxt::any walletEventOutcome(ccxt::any details) {
    ccxt::any marketId = this->safeString(details, std::string("marketId"));
    ccxt::any outcomeIndex =
        this->safeInteger(details, std::string("outcomeIndex"));
    ccxt::any outcomes = this->outcomesByMarketId(marketId);
    ccxt::any outcomesLength = getArrayLength(outcomes);
    for (ccxt::any i = 0; isLessThan(i, outcomesLength); postFixIncrement(i)) {
      ccxt::any candidate = ::getValue(outcomes, i);
      ccxt::any info =
          this->safeDict(candidate, std::string("info"), ccxt::dict{});
      if (isTrue(isEqual(this->safeInteger(info, std::string("indexSet")),
                         outcomeIndex))) {
        return candidate;
      }
    }
    // the wallet stream reports every market the wallet ever touched, including
    // ones outside the capped listing watchOrders () warms the cache from, so a
    // miss survives that warm-up. the event does name its topic and its
    // outcome, and the unified event handle and label are derived from exactly
    // those two strings - so both are rebuilt here the way parseTopicMarket
    // builds them. the market symbol and the token id are not: the first needs
    // the topic's market count and the second the on-chain id, neither of which
    // the event carries. they stay undefined rather than guessed - a handle
    // that does not match the one the rest of the api reports is worse than
    // none at all
    ccxt::any topicSlug =
        this->safeString(details, std::string("categorySlug"));
    ccxt::any eventHandle = (isTrue((!isEqual(topicSlug, ccxt::any{})))
                                 ? ccxt::any(this->shortenSlug(topicSlug))
                                 : ccxt::any(ccxt::any{}));
    ccxt::any label = this->stripPriceFormatting(
        this->safeStringUpper(details, std::string("outcomeName")));
    return ccxt::dict{
        {std::string("outcome"), ccxt::any{}},
        {std::string("outcomeId"), ccxt::any{}},
        {std::string("market"), ccxt::any{}},
        {std::string("label"), label},
        {std::string("event"), eventHandle},
        {std::string("info"), details},
    };
  }

  /**
   * @ignore
   * @method
   * @name predictfun#parseWalletEventOrder
   * @description parses a wallet event into the unified order it describes
   * @param {object} event the raw event
   * @returns {object} a [prediction order
   * structure](https://docs.ccxt.com/#/?id=prediction-order-structure)
   */
  virtual ccxt::any parseWalletEventOrder(ccxt::any event) {
    //
    //     {
    //         "type": "orderTransactionSuccess",
    //         "orderId": "3420472350",
    //         "orderHash":
    //         "0x7d097327cc15754411b7ec3e3e074ff3e974394a75aa5c81fdf90b4e67e59c15",
    //         "settlementId": "01a08f55-d6f7-77e3-895e-81cf62d8aa09",
    //         "timestamp": 1789111162000,
    //         "walletAddress": "0xabababababababababababababababababababab",
    //         "isMaker": false,
    //         "fee": { "amountWei": "400000000000000", "type": "COLLATERAL" },
    //         "fill": {
    //             "executedPriceWei": "20000000000000000",
    //             "executedSizeWei": "1000000000000000000",
    //             "executedValueWei": "20000000000000000"
    //         },
    //         "details": {
    //             "categorySlug": "will-trump-acquire-greenland-before-2027",
    //             "marketId": 2107,
    //             "marketQuestion": "Will Trump acquire Greenland before
    //             2027?", "outcome": "YES", "outcomeIndex": 1, "outcomeName":
    //             "Yes", "price": "0.010", "quantity": "1.000",
    //             "quantityFilled": "1.000",
    //             "quoteType": "ASK",
    //             "strategyType": "MARKET",
    //             "value": "0.01",
    //             "valueFilled": "0.01"
    //         }
    //     }
    //
    ccxt::any details =
        this->safeDict(event, std::string("details"), ccxt::dict{});
    ccxt::any outcomeObj = this->walletEventOutcome(details);
    ccxt::any eventType = this->safeString(event, std::string("type"));
    ccxt::any amount = this->safeString(details, std::string("quantity"));
    ccxt::any filled = this->safeString(details, std::string("quantityFilled"));
    // every variant names a state of one order, so the event type is the status
    ccxt::any status = ccxt::any{};
    if (isTrue(
            isTrue(
                isTrue(isTrue((
                           isEqual(eventType, std::string("orderAccepted")))) ||
                       isTrue((isEqual(
                           eventType, std::string("orderMarketMatchPlan"))))) ||
                isTrue((isEqual(eventType,
                                std::string("orderTransactionSubmitted"))))) ||
            isTrue(
                (isEqual(eventType, std::string("orderTransactionFailed")))))) {
      // orderMarketMatchPlan is not in the documented union but the venue does
      // send it: the order is accepted and being matched, which is the same
      // state the caller sees as open
      status = std::string("open");
    } else if (isTrue(isEqual(eventType, std::string("orderNotAccepted")))) {
      status = std::string("rejected");
    } else if (isTrue(isEqual(eventType, std::string("orderExpired")))) {
      status = std::string("expired");
    } else if (isTrue(isEqual(eventType, std::string("orderCancelled")))) {
      status = std::string("canceled");
    } else if (isTrue(isEqual(eventType,
                              std::string("orderTransactionSuccess")))) {
      // a settled fill closes the order only once nothing is left of it
      status = std::string("open");
      if (isTrue(isTrue(isTrue((!isEqual(amount, ccxt::any{}))) &&
                        isTrue((!isEqual(filled, ccxt::any{})))) &&
                 !isTrue(ccxt::Precise::stringLt(filled, amount)))) {
        status = std::string("closed");
      }
    }
    ccxt::any quoteType =
        this->safeStringLower(details, std::string("quoteType"));
    ccxt::any side = ccxt::any{};
    if (isTrue(isEqual(quoteType, std::string("bid")))) {
      side = std::string("buy");
    } else if (isTrue(isEqual(quoteType, std::string("ask")))) {
      side = std::string("sell");
    }
    ccxt::any remaining = ccxt::any{};
    if (isTrue(isTrue((!isEqual(amount, ccxt::any{}))) &&
               isTrue((!isEqual(filled, ccxt::any{}))))) {
      remaining = ccxt::Precise::stringSub(amount, filled);
    }
    ccxt::any timestamp = this->safeInteger(event, std::string("timestamp"));
    return this->safePredictionOrder(ccxt::dict{
        {std::string("id"), this->safeString2(event, std::string("orderHash"),
                                              std::string("orderId"))},
        {std::string("clientOrderId"), ccxt::any{}},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
        {std::string("lastTradeTimestamp"), ccxt::any{}},
        {std::string("lastUpdateTimestamp"), timestamp},
        {std::string("status"), status},
        {std::string("type"),
         this->safeStringLower(details, std::string("strategyType"))},
        {std::string("timeInForce"), ccxt::any{}},
        {std::string("side"), side},
        {std::string("price"), this->safeNumber(details, std::string("price"))},
        {std::string("average"), ccxt::any{}},
        {std::string("amount"), this->parseNumber(amount)},
        {std::string("filled"), this->parseNumber(filled)},
        {std::string("remaining"), this->parseNumber(remaining)},
        {std::string("cost"),
         this->safeNumber(details, std::string("valueFilled"))},
        {std::string("fee"), ccxt::any{}},
        {std::string("reduceOnly"), ccxt::any{}},
        {std::string("postOnly"), ccxt::any{}},
        {std::string("trades"), ccxt::list{}},
        {std::string("outcome"),
         this->safeOutcomeSymbol(ccxt::any{}, outcomeObj)},
        {std::string("outcomeId"),
         this->safeString(outcomeObj, std::string("outcomeId"))},
        {std::string("label"),
         this->safeString(outcomeObj, std::string("label"))},
        {std::string("market"),
         this->safeString(outcomeObj, std::string("market"))},
        {std::string("event"),
         this->safeString(outcomeObj, std::string("event"))},
        {std::string("info"), event},
    });
  }

  /**
   * @ignore
   * @method
   * @name predictfun#parseWalletEventTrade
   * @description parses the settled fill a wallet event carries
   * @param {object} event the raw event
   * @param {object} order the order the same event was parsed into
   * @returns {object} a [prediction trade
   * structure](https://docs.ccxt.com/#/?id=prediction-trade-structure)
   */
  virtual ccxt::any parseWalletEventTrade(ccxt::any event, ccxt::any order) {
    ccxt::any fill = this->safeDict(event, std::string("fill"), ccxt::dict{});
    // the fill is quoted in wei while the details block is quoted in units, so
    // only these three fields are scaled down
    ccxt::any price = ccxt::Precise::stringDiv(
        this->safeString(fill, std::string("executedPriceWei")),
        std::string("1000000000000000000"));
    ccxt::any amount = ccxt::Precise::stringDiv(
        this->safeString(fill, std::string("executedSizeWei")),
        std::string("1000000000000000000"));
    ccxt::any cost = ccxt::Precise::stringDiv(
        this->safeString(fill, std::string("executedValueWei")),
        std::string("1000000000000000000"));
    ccxt::any isMaker = this->safeBool(event, std::string("isMaker"));
    ccxt::any takerOrMaker = ccxt::any{};
    if (isTrue(!isEqual(isMaker, ccxt::any{}))) {
      takerOrMaker = (isTrue(isMaker) ? ccxt::any(std::string("maker"))
                                      : ccxt::any(std::string("taker")));
    }
    ccxt::any rawFee = this->safeDict(event, std::string("fee"));
    ccxt::any fee = ccxt::any{};
    if (isTrue(!isEqual(rawFee, ccxt::any{}))) {
      ccxt::any feeType = this->safeString(rawFee, std::string("type"));
      fee = ccxt::dict{
          {std::string("currency"),
           (isTrue((isEqual(feeType, std::string("COLLATERAL"))))
                ? ccxt::any(std::string("USDT"))
                : ccxt::any(ccxt::any{}))},
          {std::string("cost"),
           this->parseNumber(ccxt::Precise::stringDiv(
               this->safeString(rawFee, std::string("amountWei")),
               std::string("1000000000000000000")))},
      };
    }
    ccxt::any timestamp = this->safeInteger(event, std::string("timestamp"));
    return this->safePredictionTrade(ccxt::dict{
        {std::string("id"),
         this->safeString(event, std::string("settlementId"))},
        {std::string("order"),
         this->safeString(event, std::string("orderHash"))},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
        {std::string("outcome"),
         this->safeString(order, std::string("outcome"))},
        {std::string("outcomeId"),
         this->safeString(order, std::string("outcomeId"))},
        {std::string("label"), this->safeString(order, std::string("label"))},
        {std::string("market"), this->safeString(order, std::string("market"))},
        {std::string("type"), this->safeString(order, std::string("type"))},
        {std::string("side"), this->safeString(order, std::string("side"))},
        {std::string("takerOrMaker"), takerOrMaker},
        {std::string("price"), this->parseNumber(price)},
        {std::string("amount"), this->parseNumber(amount)},
        {std::string("cost"), this->parseNumber(cost)},
        {std::string("fee"), fee},
        {std::string("info"), event},
    });
  }

  /**
   * @ignore
   * @method
   * @name predictfun#handleHeartbeat
   * @description echoes the probe timestamp back, which is what keeps the
   * connection open
   * @param {Client} client the websocket client
   * @param {object} message the raw message
   */
  virtual void handleHeartbeat(ccxt::any client, ccxt::any message) {
    // ::wsClientSend(client, ) is a coroutine in the python port, so firing it
    // from this synchronous handler would drop it unsent and the venue would
    // close the socket on its next probe
    this->spawn(std::string("pong"), client, message);
  }

  /**
   * @ignore
   * @method
   * @name predictfun#pong
   * @description echoes the probe timestamp back, which is what keeps the
   * connection open
   * @param {Client} client the websocket client
   * @param {object} message the raw probe
   */
  virtual std::shared_future<ccxt::any> pong(ccxt::any client,
                                             ccxt::any message) {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        // the server probes every fifteen seconds and drops the
                        // connection on the next probe unless the exact
                        // timestamp it sent comes back, so the reply echoes it
                        // verbatim
                        ccxt::any reply = ccxt::dict{
                            {std::string("method"), std::string("heartbeat")},
                            {std::string("data"),
                             this->safeInteger(message, std::string("data"))},
                        };
                        try {
                          awaitValue(::wsClientSend(client, reply));
                        } catch (const std::exception &e) {
                          NetworkError error = NetworkError(
                              add(add(this->id, std::string(" pong failed - ")),
                                  this->exceptionMessage(e)));
                          ::wsClientReset(client, error);
                        }
                        return ccxt::any{};
                      })
        .share();
  }

  /**
   * @ignore
   * @method
   * @name predictfun#handleMessage
   * @description routes a socket message to the handler of its topic
   * @param {Client} client the websocket client
   * @param {object} message the raw message
   */
  void handleMessage(ccxt::any client, ccxt::any message) override {
    ccxt::any messageType = this->safeString(message, std::string("type"));
    if (isTrue(isEqual(messageType, std::string("R")))) {
      // a subscription reply - the venue reports a rejected topic here instead
      // of closing. it carries only the request id, so the subscription that
      // request registered is found by it - see handleSubscriptionStatus in
      // pro/binance.ts
      ccxt::any id = this->safeString(message, std::string("requestId"));
      ccxt::any subscriptionsById = this->indexBy(
          ::getValue(client, std::string("subscriptions")), std::string("id"));
      ccxt::any subscription =
          this->safeDict(subscriptionsById, id, ccxt::dict{});
      ccxt::any success =
          this->safeBool(message, std::string("success"), false);
      if (!isTrue(success)) {
        this->handleSubscriptionError(client, message, subscription);
        return;
      }
      if (isTrue(this->safeBool(subscription, std::string("unsubscribe"),
                                false))) {
        this->handleUnSubscription(client, subscription);
      }
      return;
    }
    ccxt::any topic = this->safeString(message, std::string("topic"));
    if (isTrue(isEqual(topic, std::string("heartbeat")))) {
      this->handleHeartbeat(client, message);
      return;
    }
    if (isTrue(isEqual(topic, ccxt::any{}))) {
      return;
    }
    ccxt::any parts = split(topic, std::string("/"));
    ccxt::any channel = this->safeString(parts, 0);
    if (isTrue(isEqual(channel, std::string("predictOrderbook")))) {
      this->handleOrderBook(client, message);
    } else if (isTrue(isEqual(channel, std::string("predictWalletEvents")))) {
      this->handleWalletEvent(client, message);
    }
  }

  ccxt::any nonce() override {
    // the order salt is a millisecond timestamp; incrementingNonce () reads
    // this and keeps salts unique when two identical orders are signedFlag
    // within the same millisecond
    return this->milliseconds();
  }

  /**
   * @ignore
   * @method
   * @name predictfun#sign
   * @description builds the request URL and attaches the API key header
   * required by every endpoint
   * @param {string} path the endpoint path
   * @param {string|string[]} [api] the API group and access level
   * @param {string} [method] HTTP method
   * @param {object} [params] request parameters
   * @param {object} [headers] request headers
   * @param {object} [body] request body
   * @returns {object} a dictionary with url, method, body and headers
   */
  ccxt::any sign(ccxt::any path, ccxt::any api = std::string("predictfun"),
                 ccxt::any method = std::string("GET"),
                 ccxt::any params = ccxt::dict{},
                 ccxt::any headers = ccxt::any{},
                 ccxt::any body = ccxt::any{}) override {
    // the venue authenticates every endpoint, so the key is required up front
    // rather than per access level - a key-less request is answered with a 401
    // by the API gateway. the testnet is the exception, it is served without an
    // API key at all
    ccxt::any sandboxMode =
        this->safeBool(this->options, std::string("sandboxMode"), false);
    ccxt::any apiKey = this->apiKey;
    if (isTrue(isTrue((isEqual(apiKey, ccxt::any{}))) &&
               !isTrue(sandboxMode))) {
      throw AuthenticationError(
          toString(add(this->id, std::string(" sign() requires the \"apiKey\" "
                                             "credential for all endpoints"))));
    }
    ccxt::any apiGroup =
        (isTrue(isString(api)) ? ccxt::any(api)
                               : ccxt::any(::getValue(api, 0)));
    ccxt::any baseUrls = ::getValue(this->urls, std::string("api"));
    ccxt::any baseUrl = this->safeString(
        baseUrls, apiGroup, ::getValue(baseUrls, std::string("predictfun")));
    ccxt::any url =
        add(add(baseUrl, std::string("/")), this->implodeParams(path, params));
    ccxt::any query = this->omit(params, this->extractParams(path));
    if (isTrue(isEqual(method, std::string("GET")))) {
      if (isTrue(isGreaterThan(getArrayLength(getObjectKeys(query)), 0))) {
        url = add(url, add(std::string("?"), this->urlencode(query)));
      }
    }
    ccxt::any existingHeaders =
        (isTrue((!isEqual(headers, ccxt::any{}))) ? ccxt::any(headers)
                                                  : ccxt::any(ccxt::dict{}));
    headers = existingHeaders;
    ccxt::any authHeaders = ccxt::dict{};
    if (isTrue(isTrue((!isEqual(apiKey, ccxt::any{}))) &&
               isTrue((!isTrue(sandboxMode))))) {
      // the php transpiler prefixes every standalone 'api' with a $, string
      // literals included, since sign () has a parameter of that name - ending
      // the literal right after it avoids that
      ccxt::any apiKeyHeader = add(std::string("x-api"), std::string("-key"));
      ::setValue(authHeaders, apiKeyHeader, apiKey);
    }
    // the API key authorises the request, the JWT authorises acting for a
    // wallet - authenticate () caches it, so it is attached to every call once
    // an order action has asked for one the JWT is scoped to one wallet, so it
    // only goes to the endpoints that act for a wallet. attaching it to public
    // reads would hand the venue a wallet credential they do not need. note
    // v1/positions/{address} reads someone else's positions and is deliberately
    // absent, as is v1/orders/matches, which is the public trade feed
    ccxt::any walletPaths = ccxt::list{std::string("v1/orders"),
                                       std::string("v1/orders/{hash}"),
                                       std::string("v1/orders/remove"),
                                       std::string("v1/orders/remove-by-hash"),
                                       std::string("v1/account"),
                                       std::string("v1/account/activity"),
                                       std::string("v1/account/referral"),
                                       std::string("v1/positions"),
                                       std::string("v1/oauth/finalize"),
                                       std::string("v1/oauth/orders"),
                                       std::string("v1/oauth/orders/create"),
                                       std::string("v1/oauth/orders/cancel"),
                                       std::string("v1/oauth/positions")};
    ccxt::any jwtToken =
        this->safeString(this->options, std::string("jwtToken"));
    // unlike the API key, the JWT IS required on the testnet - wallet endpoints
    // there answer 401 without it, so it is attached on both hosts
    if (isTrue(isTrue((!isEqual(jwtToken, ccxt::any{}))) &&
               isTrue(this->inArray(path, walletPaths)))) {
      ::setValue(authHeaders, std::string("Authorization"),
                 add(std::string("Bearer "), jwtToken));
    }
    if (isTrue(!isEqual(method, std::string("GET")))) {
      if (!isTrue(sandboxMode)) {
        this->checkRequiredCredentials();
      }
      ::setValue(authHeaders, std::string("Content-Type"),
                 std::string("application/json"));
      body = this->json(params);
    }
    headers = this->extend(headers, authHeaders);
    return ccxt::dict{
        {std::string("url"), url},
        {std::string("method"), method},
        {std::string("body"), body},
        {std::string("headers"), headers},
    };
  }
